#pragma once
// The per-iteration kernels of the node-line smoother generated by MARSIR, from
// marsir-mlir/generated/lines_p{p}_sm90.ptx (test/dss_gpu_pipeline.py p --lines, from
// mlir_ir.emit_lines), behind cellwise::LineKernels for cellwise::NodeLines
// (mars_cellwise_lines.hpp): the residual DSS (mir.dss of b or b - y), the block solves
// (structured loops, one lane per block, on the layout padded to 128 blocks) and the Chebyshev
// update (mir.dss of the counting-copy values with an epilogue). CPU gate:
// marsir-mlir/tools/emu_lines.cpp, bit for bit against the hand kernels' formulas. On the GPU
// the generated code does not fuse multiply-adds and nvcc fuses them in the hand kernels, so
// the two agree to rounding.

#include "backend/distributed/unstructured/marsir/mars_marsir_ptx_cellwise.hpp"
#include "backend/distributed/unstructured/solvers/mars_cellwise_lines.hpp"

#include <string>
#include <vector>

namespace mars {
namespace marsir {

class LinesPtx : public CellwisePtx, public cellwise::LineKernels {
public:
    LinesPtx(const std::string& dir, int p, const cellwise::UnstructuredTopology& T)
        : CellwisePtx(dir + "/lines_p" + std::to_string(p) + "_sm90.ptx", p), T_(T)
    {
        const std::string q = "_p" + std::to_string(p);
        residual_[0] = function("lines_residual0" + q);
        residual_[1] = function("lines_residual" + q);
        update_[0] = function("lines_update_first0" + q);
        update_[1] = function("lines_update_first" + q);
        update_[2] = function("lines_update_next" + q);
        solve_ = function("lines_solve" + q);
    }

    void residual(const double* b, const double* y, const double* ghost, const cellwise::ElementList& set, double* s,
                  cudaStream_t stream) override
    {
        if (set.count == 0) return;
        const long long L = T_.local * n3();
        std::vector<Arg> a = topology_args(b, ghost, T_, set);
        if (y) a.insert(a.begin() + 2, Arg{y, L});   // (b, ghost, y, elements, tables..., s)
        a.push_back({s, L});
        launch(residual_[y ? 1 : 0], a, set.count, stream);
    }

    void solve(const double* L, const long long* copy, long long slots, const int* len, const long long* warp_off,
               long long blocks, const double* s, double* z, cudaStream_t stream) override
    {
        const long long values = T_.local * n3();
        std::vector<Arg> a{{L, slots * 32 * (p_ + 1)}, {copy, slots * 32}, {len, blocks}, {warp_off, blocks / 32 + 1},
                           {s, values}, {z, values}};
        launch(solve_, a, blocks, stream);
    }

    void update(int kind, const double* z, const double* ghost, const cellwise::ElementList& set, double* d, double* x,
                double c1, double c2, cudaStream_t stream) override
    {
        if (set.count == 0) return;
        const long long L = T_.local * n3();
        std::vector<Arg> a = topology_args(z, ghost, T_, set);
        a.push_back(vec(T_.counting));
        a.push_back(vec(T_.edge_dirichlet));
        a.push_back(vec(T_.vert_dirichlet));
        a.push_back({d, L});
        a.push_back({x, L});
        launch(update_[kind], a, set.count, stream, {}, {c1, c2});
    }

private:
    const cellwise::UnstructuredTopology& T_;
    CUfunction residual_[2] = {}, update_[3] = {}, solve_ = nullptr;
};

}  // namespace marsir
}  // namespace mars
